 export const ZONES_URL = "https://tzdata.ops.internal/v1/zones";

+/** Validate zone name format */
+function validateZoneName(name: string): void {
+  if (!name || typeof name !== 'string') {
+    throw new RangeError("Invalid zone name");
+  }
+  
+  // Split by '/'
+  const parts = name.split('/');
+  if (parts.length < 2) {
+    throw new RangeError("Invalid zone name");
+  }
+  
+  // First part: only letters and _
+  if (!parts[0].match(/^[a-zA-Z_]+$/)) {
+    throw new RangeError("Invalid zone name");
+  }
+  
+  // Other parts: letters, digits, _, +, -
+  for (let i = 1; i < parts.length; i++) {
+    if (!parts[i].match(/^[a-zA-Z0-9_+\-]+$/)) {
+      throw new RangeError("Invalid zone name");
+    }
+    if (parts[i] === '') {
+      throw new RangeError("Invalid zone name");
+    }
+  }
+}
